import hashlib,json,re,subprocess
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path('/private/tmp/pathwaymech-next-251-20261014')
DOS=ROOT/'research/pathway_additions/2026-10-14-next-251/gentisate'
OUT=Path('/private/tmp/pathwaymech-next-251-integration-review')
cache={}
def sha(path):
    path=Path(path).resolve()
    if path not in cache:
        h=hashlib.sha256()
        with path.open('rb') as s:
            for b in iter(lambda:s.read(1024*1024),b''):h.update(b)
        cache[path]=h.hexdigest()
    return cache[path]
retained=json.loads((DOS/'retained-projections.json').read_text())['files']
projection_checks=[]
for x in retained:
    current=DOS/x['path']; original=Path(x['external_source'])
    projection_checks.append({'path':x['path'],'retained_hash_match':sha(current)==x['sha256'],'external_hash_match':sha(original)==x['sha256']})
originals=[]; seen=set()
def walk(x,owner):
    if isinstance(x,dict):
        raw=x.get('path');h=x.get('sha256')
        if isinstance(raw,str) and raw.startswith('/private/tmp/') and isinstance(h,str) and re.fullmatch('[0-9a-f]{64}',h):
            key=(raw,h)
            if key not in seen:
                seen.add(key);p=Path(raw)
                originals.append({'manifest':owner,'path':raw,'exists':p.is_file(),'sha256':h,'hash_match':p.is_file() and sha(p)==h})
        for value in x.values():walk(value,owner)
    elif isinstance(x,list):
        for value in x:walk(value,owner)
for p in DOS.rglob('*.json'):
    if 'integration-review' not in p.parts:walk(json.loads(p.read_text()),str(p.relative_to(DOS)))
for x in json.loads((DOS/'primary/source-artifacts.json').read_text()):
    p=Path('/private/tmp/pathwaymech-next-251-primary-20261014')/x['path']
    originals.append({'manifest':'primary/source-artifacts.json','path':str(p),'exists':p.is_file(),'sha256':x['sha256'],'hash_match':p.is_file() and sha(p)==x['sha256']})
# os-backed traversal includes hidden and gitignored files, with no symlink traversal.
files=sorted(p for p in DOS.rglob('*') if p.is_file())
raw=[];secrets=[]
patterns=[re.compile(rb'(?im)^set-cookie\s*:'),re.compile(rb'(?i)"(?:set-cookie|authorization|cookie)"\s*:\s*"[^"\n]{8,}"'),re.compile(rb'\bgh[pousr]_[A-Za-z0-9]{30,}\b'),re.compile(rb'\bgithub_pat_[A-Za-z0-9_]{30,}\b')]
for p in files:
    data=p.read_bytes()
    if p.suffix.lower() in {'.pdf','.gz','.zip','.xml','.db','.cif','.jpg','.jpeg','.png','.html'} or data.startswith((b'%PDF-',b'<?xml',b'<!DOCTYPE html')):
        raw.append(str(p.relative_to(DOS)))
    if any(pattern.search(data) for pattern in patterns):secrets.append(str(p.relative_to(DOS)))
report={'observed_utc':datetime.now(timezone.utc).isoformat(),'scope':'Every file under next251/gentisate including hidden and gitignored entries; no symlink traversal, .git and other repository cohorts outside scope. Raw originals remain external. Pattern scanning is bounded, not a general secret-certification.','files':len(files),'retained_projections':projection_checks,'original_artifact_bindings':originals,'raw_files':raw,'credential_pattern_files':secrets,'external_unique_files_hashed':len(cache)}
bindings=json.loads((DOS/'reference-bindings.json').read_text())
bound_refs=[]
for item in bindings['bindings']:
    if item.get('source_sha256'):
        paths=item['verified_external_artifacts']
        bound_refs.append({'reference_id':item['reference_id'],'hash_verified':bool(paths) and all(sha(p)==item['source_sha256'] for p in paths)})
    else:
        bound_refs.append({'reference_id':item['reference_id'],'no_hash_claimed':True,'scope_explicit':bool(item.get('hash_scope'))})
report['record_reference_bindings']={'record_hash_matches':sha(ROOT/'data/pathways/gentisate-degradation-i.yaml')==bindings['record_sha256'],'references':bound_refs}
report['passed']=all(x['retained_hash_match'] and x['external_hash_match'] for x in projection_checks) and all(x['exists'] and x['hash_match'] for x in originals) and not raw and not secrets
report['passed']=report['passed'] and report['record_reference_bindings']['record_hash_matches'] and all(x.get('hash_verified',x.get('scope_explicit',False)) for x in bound_refs)
(OUT/'retention-audit.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'passed':report['passed'],'files':len(files),'projections':len(projection_checks),'original_bindings':len(originals),'hash_failures':[x for x in originals if not x['hash_match']],'projection_failures':[x for x in projection_checks if not x['retained_hash_match'] or not x['external_hash_match']],'raw_files':raw,'credential_pattern_files':secrets},indent=2))
